using Watchpoint.Kernel.Results;

namespace Watchpoint.State.Contracts;

/// <summary>Domain errors generated by the State module (STA §10).</summary>
public static class StateErrors
{
    /// <summary><c>state.entity.not_found</c>: no state for the given id (unknown or deleted).</summary>
    public static Error EntityNotFound(Guid id) => Error.NotFound("state.entity.not_found", ("id", id));

    /// <summary><c>state.query.too_many_ids</c>: a batch query exceeded its id limit.</summary>
    public static Error QueryTooManyIds(int max) => Error.Create(ErrorKind.Validation, "state.query.too_many_ids", ("max", max));

    /// <summary><c>state.query.invalid_condition</c>: the <c>where</c> path is unknown or its value is invalid.</summary>
    public static Error QueryInvalidCondition(string path) => Error.Create(ErrorKind.Validation, "state.query.invalid_condition", ("path", path));
}
